sys_script_client.script:
function onSubmit() {

	// 1. Get the raw date values from the fields
    var admissionStr = g_form.getValue('admission_date');
    var graduationStr = g_form.getValue('graduated_date');

    // If either date is empty, skip validation and let mandatory rules handle it
    if (!admissionStr || !graduationStr) {
        return true;
    }

    // 2. Fetch the logged-in user's system date format configuration
    var userDateFormat = g_user_date_format; 

    // 3. Convert string dates securely into numeric timestamps using ServiceNow utilities
    var admissionMs = getDateFromFormat(admissionStr, userDateFormat);
    var graduationMs = getDateFromFormat(graduationStr, userDateFormat);

    // Validate that the strings were successfully parsed into numbers
    if (admissionMs === 0 || graduationMs === 0) {
        return true; // Skips if formats are unparseable to avoid locking the form
    }

    // Condition 1: Check if the admission date is later than the graduation date
    if (admissionMs > graduationMs) {
        g_form.addErrorMessage('Validation Error: The admission date must not be later than the graduation date.');
        return false; // Blocks form submission
    }

    // Condition 2: Check for a minimum gap of 3 years
    // Create standard JavaScript Date objects from the parsed milliseconds
    var admissionDate = new Date(admissionMs);
    var graduationDate = new Date(graduationMs);

    // Calculate the target minimum date by adding exactly 3 years to admission
    var minGraduationDate = new Date(admissionDate.getTime());
    minGraduationDate.setFullYear(minGraduationDate.getFullYear() + 3);

    if (graduationDate < minGraduationDate) {
        g_form.addErrorMessage('Validation Error: There must be a minimum gap of 3 years between the admission date and graduation date.');
        return false; // Blocks form submission
    }

    return true; // Allows the form to save if both conditions pass

}
